import React, { useState, useRef, useEffect } from 'react';
import { processColorblindImageData } from './utils/colorblindProcessing';

const CameraProcessor = ({ colorblindType = 'protanopia', mode = 'simulate' }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);

  const stopCamera = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setStreaming(false);
  };

  const drawFrame = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || video.readyState < 2) {
      animationFrameRef.current = requestAnimationFrame(drawFrame);
      return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      setError('Canvas rendering context is not available');
      return;
    }

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    ctx.putImageData(processColorblindImageData(imageData, colorblindType, mode), 0, 0);

    animationFrameRef.current = requestAnimationFrame(drawFrame);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  useEffect(() => {
    if (!streaming) {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
      return;
    }

    drawFrame();

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
    };
  }, [streaming, colorblindType, mode]);

  const startCamera = async () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;

    if (!video || !canvas) {
      setError('Video or canvas element not ready');
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current = stream;
      video.srcObject = stream;

      video.onloadedmetadata = () => {
        const sourceWidth = video.videoWidth || 640;
        const sourceHeight = video.videoHeight || 480;
        const maxWidth = 640;
        const scale = Math.min(1, maxWidth / sourceWidth);

        canvas.width = Math.max(1, Math.round(sourceWidth * scale));
        canvas.height = Math.max(1, Math.round(sourceHeight * scale));

        video.play().then(() => {
          setStreaming(true);
          setError(null);
        }).catch(err => setError('Failed to play video: ' + err.message));
      };
    } catch (err) {
      setError('Camera access error: ' + err.message);
    }
  };

  return (
    <div className="component-container">
      <h2>Live Camera Processor</h2>

      {error && <div style={{ color: 'red', marginBottom: '10px' }}>{error}</div>}

      <div
        className="upload-area"
        style={{
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #5d35c4',
          borderRadius: '8px',
          backgroundColor: '#fdfdfd',
          cursor: 'pointer',
        }}
        onClick={streaming ? stopCamera : startCamera}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Click to start your camera</p>
            <p style={{ fontSize: '14px', color: '#666' }}>Live camera feed will appear below</p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>Camera is active (click to stop)</p>
        )}
      </div>

      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '20px',
          marginTop: '20px',
          flexWrap: 'wrap',
        }}
      >
        <div>
          <p style={{ textAlign: 'center' }}>Original</p>
          <video
            ref={videoRef}
            style={{
              width: '320px',
              border: '2px solid #ddd',
              borderRadius: '8px',
            }}
            autoPlay
            playsInline
            muted
          />
        </div>

        <div>
          <p style={{ textAlign: 'center' }}>Filtered</p>
          <canvas
            ref={canvasRef}
            style={{
              width: '320px',
              border: '2px solid #ddd',
              borderRadius: '8px',
            }}
          />
        </div>
      </div>

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button
          className="button"
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            borderRadius: '8px',
            border: 'none',
            backgroundColor: '#5d35c4',
            color: '#fff',
            cursor: 'pointer',
            transition: 'background-color 0.3s',
          }}
          onClick={streaming ? stopCamera : startCamera}
          onMouseEnter={e => (e.currentTarget.style.backgroundColor = '#5d35c4')}
          onMouseLeave={e => (e.currentTarget.style.backgroundColor = '#5d35c4')}
        >
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
